public RefreshFrequency xds()
{
    METGUPRebateAgreementTypeByStatePolicyTmp   metGUPRebateAgreementTypeNameByStateTmp;
    GUPRebateAgreementType                      gupRebateAgreementType;
    METUserSecurityGroupList                    metUserSecurityGroupList;
    METUserSecurityStateList                    metUserSecurityStateList;

    Unchecked(Uncheck::XDS)
    {
        while select crosscompany TypeName,DataAreaId from gupRebateAgreementType
            group by TypeName,DataAreaId
            join metUserSecurityStateList
                where metUserSecurityStateList.METLogisticsAddressStateId == gupRebateAgreementType.METLogisticsAddressStateId
                    && metUserSecurityStateList.Company == gupRebateAgreementType.DataAreaId
            join metUserSecurityGroupList
                where metUserSecurityGroupList.UserSecurityGroupId == metUserSecurityStateList.UserSecurityGroupId
                    && metUserSecurityGroupList.UserId == curUserId()
        {
            metGUPRebateAgreementTypeNameByStateTmp.TypeName = gupRebateAgreementType.TypeName;
            metGUPRebateAgreementTypeNameByStateTmp.Company = gupRebateAgreementType.DataAreaId;
            metGUPRebateAgreementTypeNameByStateTmp.insert();
        }
    }

    return RefreshFrequency::PerSession;
}
